{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and use rules (2026 amount)","requirement":"A landlord may charge no more than the annual state screening fee cap, must give the applicant a copy of any credit report obtained, a receipt and itemized costs, refund any unused portion, and accept a reusable screening report.","key_value":"$68.96 for 2026","coverage_conditions":"Prospective tenants screened for residential rental units; the page states the cap applies as the maximum tenant screening fee.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"residential rental screening"},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley notice of tenant screening fee rights and state cap","requirement":"An owner who charges a screening fee must give the applicant, in the application or in a separate disclosure before taking the fee, a clear tenant screening fee rights statement and a statement of the maximum fee cap under California Civil Code Section 1950.6(b).","key_value":null,"coverage_conditions":"Owners or their agents receiving a request to rent residential property in Berkeley and charging a fee to purchase a consumer credit report and process the application.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"residential property in Berkeley"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code § 13.78.010","quoted_span":"the owner must provide, either in the rental application or in a separate disclosure before receiving the fee, a clear and conspicuous tenant screening fee rights statement and a statement of the maximum fee cap permitted under","interaction":"State cap and notice duty under California Civil Code Section 1950.6(b)","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley ban on non-refundable fees to existing tenants","requirement":"An owner of residential rental property, or the owner’s agent, may not charge an existing tenant a non-refundable fee to renew a tenancy, including fees tied to a roommate leaving or a request to add or replace a roommate in a pre-existing household.","key_value":null,"coverage_conditions":"Existing tenants of residential rental property in Berkeley, including pre-existing households with roommate changes or renewal requests.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"existing tenancies"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code § 13.78.016","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley Chapter 13.78 applies to all rental agreements","requirement":"Chapter 13.78 applies to all residential rental agreements regardless of contrary lease language, and any lease provision violating the chapter is unenforceable.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, existing or new.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"all residential rental agreements"},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the provisions of this chapter are unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code § 13.78.018","quoted_span":"Chapter 13.78 applies to all residential rental agreements regardless of any contractual language in any rental agreement or lease to the contrary.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
